(() => {
  'use strict';

  const DEFAULTS = { enabled: true, threshold: 0.65, minDimension: 96, maxImagesPerPage: 100 };
  const records = new Map();
  const pending = [];
  let settings = { ...DEFAULTS };
  let running = false;
  let queueScheduled = false;
  let scannedCount = 0;
  let overlayHost;
  let overlayRoot;
  let positionScheduled = false;

  initialize().catch(() => {});

  async function initialize() {
    settings = await chrome.storage.local.get(DEFAULTS);
    createOverlay();
    if (settings.enabled) scan(document);

    const observer = new MutationObserver((mutations) => {
      if (!settings.enabled) return;
      for (const mutation of mutations) {
        if (mutation.type === 'attributes' && mutation.target instanceof HTMLImageElement) {
          consider(mutation.target, true);
        }
        for (const node of mutation.addedNodes) {
          if (node instanceof HTMLImageElement) consider(node);
          else if (node instanceof Element) scan(node);
        }
      }
      schedulePositions();
    });
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['src', 'srcset', 'sizes']
    });

    addEventListener('scroll', schedulePositions, { passive: true, capture: true });
    addEventListener('resize', schedulePositions, { passive: true });
    setInterval(schedulePositions, 1500);

    chrome.storage.onChanged.addListener((changes, area) => {
      if (area !== 'local') return;
      for (const key of Object.keys(DEFAULTS)) {
        if (changes[key]) settings[key] = changes[key].newValue;
      }
      if (!settings.enabled) clearAll();
      else scan(document);
    });

    chrome.runtime.onMessage.addListener((message) => {
      if (message?.target === 'content' && message.type === 'SET_ENABLED') {
        settings.enabled = Boolean(message.enabled);
        if (settings.enabled) scan(document);
        else clearAll();
      }
    });
  }

  function createOverlay() {
    overlayHost = document.createElement('div');
    overlayHost.id = 'local-ai-detector-overlay';
    overlayHost.setAttribute('aria-live', 'polite');
    overlayRoot = overlayHost.attachShadow({ mode: 'open' });
    const style = document.createElement('style');
    style.textContent = `
      :host { all: initial !important; position: absolute !important; top: 0 !important; left: 0 !important;
        width: 0 !important; height: 0 !important; overflow: visible !important; z-index: 2147483647 !important;
        pointer-events: none !important; font-family: ui-sans-serif, system-ui, -apple-system, sans-serif !important; }
      .badge { position: absolute; display: inline-flex; align-items: center; gap: 5px; box-sizing: border-box;
        min-height: 25px; padding: 4px 8px; border-radius: 999px; border: 1px solid rgba(255,255,255,.2);
        color: #fff; background: rgba(19,24,31,.92); box-shadow: 0 4px 14px rgba(0,0,0,.28);
        backdrop-filter: blur(8px); font: 700 11px/1.1 ui-sans-serif, system-ui, sans-serif;
        letter-spacing: .01em; white-space: nowrap; pointer-events: auto; cursor: help; }
      .badge::before { content: ''; width: 7px; height: 7px; flex: 0 0 auto; border-radius: 50%; background: #aeb7c4; }
      .badge.pending::before { background: #f6be5f; animation: pulse 1.1s infinite; }
      .badge.ai { background: rgba(153,43,35,.95); }
      .badge.ai::before { background: #ffb09e; box-shadow: 0 0 0 3px rgba(255,176,158,.16); }
      .badge.real { background: rgba(20,92,77,.94); }
      .badge.real::before { background: #7ce0bb; }
      .badge.error { background: rgba(66,72,83,.94); color: #e7eaf0; }
      .badge.setup { background: rgba(126,78,22,.95); cursor: pointer; }
      .badge[hidden] { display: none !important; }
      @keyframes pulse { 50% { opacity: .35; transform: scale(.8); } }
      @media (prefers-reduced-motion: reduce) { .badge.pending::before { animation: none; } }
    `;
    overlayRoot.append(style);
    document.documentElement.append(overlayHost);
  }

  function scan(root) {
    if (root instanceof HTMLImageElement) consider(root);
    root.querySelectorAll?.('img').forEach((image) => consider(image));
  }

  function consider(image, sourceChanged = false) {
    if (!settings.enabled || scannedCount >= settings.maxImagesPerPage) return;
    if (!(image instanceof HTMLImageElement)) return;

    if (!image.complete || !image.naturalWidth) {
      image.addEventListener('load', () => consider(image, true), { once: true });
      return;
    }

    const rect = image.getBoundingClientRect();
    if (image.naturalWidth < settings.minDimension || image.naturalHeight < settings.minDimension) return;
    if (rect.width < 48 || rect.height < 48 || getComputedStyle(image).display === 'none') return;

    const url = image.currentSrc || image.src;
    if (!url) return;
    const existing = records.get(image);
    if (existing && existing.url === url && !sourceChanged) return;
    if (existing && existing.url === url && sourceChanged && existing.state !== 'error') return;

    removeRecord(image);
    const badge = document.createElement('span');
    badge.className = 'badge pending';
    badge.textContent = 'Scanning locally';
    badge.title = 'Queued for private on-device analysis.';
    overlayRoot.append(badge);
    records.set(image, { image, badge, url, state: 'pending' });
    scannedCount += 1;
    pending.push(image);
    schedulePositions();
    scheduleQueue();
  }

  function scheduleQueue() {
    if (queueScheduled || running || !settings.enabled) return;
    queueScheduled = true;
    queueMicrotask(() => {
      queueScheduled = false;
      runQueue();
    });
  }

  async function runQueue() {
    if (running || !settings.enabled) return;
    running = true;
    while (pending.length && settings.enabled) {
      pending.sort((left, right) => queuePriority(left) - queuePriority(right));
      const image = pending.shift();
      const record = records.get(image);
      if (!record || record.state !== 'pending' || !image.isConnected || record.url !== (image.currentSrc || image.src)) continue;
      await analyze(record);
    }
    running = false;
  }

  function queuePriority(image) {
    const rect = image.getBoundingClientRect();
    const visible = rect.bottom > 0 && rect.right > 0 && rect.top < innerHeight && rect.left < innerWidth;
    if (visible) return -1_000_000 + Math.max(0, rect.top);
    if (rect.top >= innerHeight) return rect.top - innerHeight;
    if (rect.bottom <= 0) return -rect.bottom + innerHeight;
    return 500_000;
  }

  async function analyze(record) {
    const directUrl = normalizeDirectUrl(record.url);
    let result;
    if (directUrl) {
      result = await requestAnalysis({ url: directUrl });
      if (!result.ok && result.errorCode === 'IMAGE_FETCH_FAILED') {
        const dataUrl = captureFallback(record.image);
        if (dataUrl) result = await requestAnalysis({ dataUrl, mimeType: 'image/jpeg' });
      }
    } else {
      const dataUrl = captureFallback(record.image);
      result = dataUrl
        ? await requestAnalysis({ dataUrl, mimeType: 'image/jpeg' })
        : { ok: false, errorCode: 'IMAGE_CAPTURE_FAILED', error: 'Chrome could not capture this protected or local image.' };
    }

    if (!records.has(record.image)) return;
    if (!result.ok) {
      showError(record, result);
      return;
    }

    const value = result.result;
    record.state = value.isAI ? 'ai' : 'real';
    record.badge.className = `badge ${record.state}`;
    const displayedClass = value.isAI ? 'AI' : 'REAL';
    record.badge.textContent = `${displayedClass} ${Math.round(value.classConfidence * 100)}%`;
    const evidence = value.evidence?.length ? ` Evidence: ${value.evidence.join(', ')}.` : '';
    const threadDetail = value.backend === 'WebAssembly' ? ` using ${value.wasmThreads || 1} thread${value.wasmThreads === 1 ? '' : 's'}` : '';
    record.badge.title = `${displayedClass} classification at the fixed ${Math.round(value.threshold * 100)}% AI threshold. ` +
      `Displayed ${displayedClass} confidence: ${(value.classConfidence * 100).toFixed(1)}%. ` +
      `AI likelihood: ${(value.aiProbability * 100).toFixed(1)}%; real likelihood: ${((1 - value.aiProbability) * 100).toFixed(1)}%. ` +
      `Model inference: ${value.inferenceMs} ms; total processing: ${value.totalMs ?? value.inferenceMs} ms ` +
      `with ${value.backend}${threadDetail}.${evidence} Scores are probabilistic, not proof.`;
    record.image.dataset.localAiScore = value.aiProbability.toFixed(6);
    record.image.dataset.localAiVerdict = value.isAI ? 'ai' : 'real';
    record.image.dataset.localAiConfidence = value.classConfidence.toFixed(6);
    record.image.dataset.localAiThreshold = String(value.threshold);
    schedulePositions();
  }

  async function requestAnalysis(payload) {
    try {
      return await chrome.runtime.sendMessage({ target: 'background', type: 'ANALYZE_IMAGE', payload });
    } catch (error) {
      return { ok: false, errorCode: 'EXTENSION_ERROR', error: error?.message || String(error) };
    }
  }

  function normalizeDirectUrl(url) {
    try {
      const parsed = new URL(url, location.href);
      return /^https?:$/.test(parsed.protocol) ? parsed.href : '';
    } catch {
      return '';
    }
  }

  function captureFallback(image) {
    try {
      const max = 1024;
      const scale = Math.min(1, max / Math.max(image.naturalWidth, image.naturalHeight));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      const context = canvas.getContext('2d');
      context.fillStyle = '#fff';
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      return canvas.toDataURL('image/jpeg', 0.92);
    } catch {
      return null;
    }
  }

  function showError(record, result) {
    record.state = 'error';
    const needsSetup = result.errorCode === 'NOT_INSTALLED' ||
      result.errorCode === 'BUNDLED_MODEL_MISSING';
    record.badge.className = `badge ${needsSetup ? 'setup' : 'error'}`;
    record.badge.textContent = needsSetup ? 'Set up detector' : 'Not analyzed';
    record.badge.title = result.error || 'This image could not be analyzed locally.';
    if (needsSetup) {
      record.badge.addEventListener('click', () => {
        chrome.runtime.sendMessage({ target: 'background', type: 'OPEN_SETUP' }).catch(() => {});
      }, { once: true });
    }
    schedulePositions();
  }

  function schedulePositions() {
    if (positionScheduled) return;
    positionScheduled = true;
    requestAnimationFrame(() => {
      positionScheduled = false;
      updatePositions();
    });
  }

  function updatePositions() {
    for (const [image, record] of records) {
      if (!image.isConnected) {
        removeRecord(image);
        continue;
      }
      const rect = image.getBoundingClientRect();
      const visible = rect.bottom > 0 && rect.right > 0 && rect.top < innerHeight && rect.left < innerWidth && rect.width >= 48 && rect.height >= 48;
      record.badge.hidden = !visible;
      if (visible) {
        // Document-space positioning lets Chrome's compositor move badges with
        // the page itself instead of leaving viewport-fixed labels behind.
        record.badge.style.left = `${Math.max(4, rect.left + window.scrollX + 6)}px`;
        record.badge.style.top = `${Math.max(4, rect.top + window.scrollY + 6)}px`;
      }
    }
  }

  function removeRecord(image) {
    const record = records.get(image);
    if (!record) return;
    record.badge.remove();
    delete image.dataset.localAiScore;
    delete image.dataset.localAiVerdict;
    delete image.dataset.localAiConfidence;
    delete image.dataset.localAiThreshold;
    records.delete(image);
  }

  function clearAll() {
    pending.length = 0;
    for (const image of [...records.keys()]) removeRecord(image);
    scannedCount = 0;
  }
})();
